insert into quiz_private.questions (id, category, question_bs, question_en, options_bs, options_en, correct_option, explanation_bs, explanation_en, source_name, source_url) values
('ocimaljubavi', 'ljudi', 'U kojem je gradu Zavičajni muzej predstavio knjigu „Bosna i Hercegovina očima ljubavi“ povodom Dana nezavisnosti 2022?', 'Which town’s regional museum presented Bosna i Hercegovina očima ljubavi for Independence Day in 2022?', '["Travnik","Jajce","Bihać","Konjic"]', '["Travnik","Jajce","Bihać","Konjic"]', '1', 'Sinanović je svoje fotografije predstavio publici u Travniku.', 'Sinanović presented his photographs to an audience in Travnik.', 'Zavičajni muzej Travnik', 'https://muzejtravnik.ba/obiljezavanje-1-marta-dana-nezavisnosti-bosne-i-hercegovine-promocija-fotomonografije-samira-sinanovica-bosna-i-hercegovina-ocima-ljubavi/'),
('galerijafaber', 'dogadjaji', 'U kojem je gradu Umjetnička galerija BiH 2026. predstavila Sinanovićevu izložbu „Homo faber“?', 'In which city did the National Gallery of Bosnia and Herzegovina present Sinanović’s Homo faber exhibition in 2026?', '["Mostar","Tuzla","Zenica","Sarajevo"]', '["Mostar","Tuzla","Zenica","Sarajevo"]', '4', 'Izložba u Sarajevu pratila je istoimenu fotomonografiju.', 'The Sarajevo exhibition accompanied the photo book of the same name.', 'Umjetnička galerija BiH', 'https://ugbih.ba/?p=8730'),
('peticabliha', 'dogadjaji', 'Kuda su učesnici prve Sanske petice pozvani na izlet nakon utrke?', 'Where were runners invited to go after the first Sanska petica race?', '["Na Grmeč","U Kamengrad","Na vodopad Blihe","Na izvorište Zdene"]', '["To Grmeč","To Kamengrad","To Bliha Waterfall","To the Zdena spring"]', '3', 'Nakon utrke 2025. za učesnike je organizovana posjeta vodopadu Blihe.', 'A visit to Bliha Waterfall was organised for participants after the 2025 race.', 'Nezavisne novine', 'https://www.nezavisne.com/novosti/gradovi/Sanska-petica-opravdala-ocekivanja-Istrcao-trku-gurajuci-bebu-u-kolicima/931129'),
('vodeneigre', 'dogadjaji', 'Koju je novost organizator najavio na otvaranju Ljeta na Sani 2025?', 'What new activity did the organiser announce at the opening of Ljeto na Sani in 2025?', '["Igre na vodi","Noćni maraton","Regatu jedrilica","Utrku splavova"]', '["Water games","A night marathon","A sailing regatta","A raft race"]', '1', 'Najavljene su igre i takmičenja na vodi.', 'The organiser announced games and competitions on the water.', 'Nezavisne novine', 'https://www.nezavisne.com/novosti/gradovi/Otvoreno-Ljeto-na-Sani-Ove-godine-nece-ucestvovati-zvucna-imena/916157'),
('devet', 'priroda', 'Sanski Most se zove grad na devet rijeka. Koliko je rječica uz Sanu?', 'Sanski Most is called the town on nine rivers. How many smaller rivers run alongside the Sana?', '["6","7","8","9"]', '["6","7","8","9"]', '3', 'Osam: Sanica, Dabar, Zdena, Bliha, Majdanska rijeka, Japra, Sasinka i Kozica. Sa Sanom to je devet.', 'Eight: the Sanica, Dabar, Zdena, Bliha, Majdanska rijeka, Japra, Sasinka and Kozica. With the Sana that makes nine.', 'Općina Sanski Most: Otkrijte Sanski Most', 'https://sanskimost.gov.ba/otkrijte-sanski-most-biser-krajine-koji-spaja-prirodu-i-tradiciju/'),
('nijeriv', 'priroda', 'Koja od ovih rijeka nije među devet sanskih rijeka?', 'Which of these rivers is not among the nine rivers of Sanski Most?', '["Zdena","Una","Japra","Dabar"]', '["Zdena","Una","Japra","Dabar"]', '2', 'Una. Uz Sanu su to Sanica, Dabar, Zdena, Bliha, Majdanska rijeka, Japra, Sasinka i Kozica.', 'The Una. Besides the Sana they are the Sanica, Dabar, Zdena, Bliha, Majdanska rijeka, Japra, Sasinka and Kozica.', 'Općina Sanski Most: Otkrijte Sanski Most', 'https://sanskimost.gov.ba/otkrijte-sanski-most-biser-krajine-koji-spaja-prirodu-i-tradiciju/'),
('najduza', 'priroda', 'Koja je najduža od devet rijeka koje teku kroz Sanski Most?', 'Which is the longest of the nine rivers that flow through Sanski Most?', '["Bliha","Japra","Dabar","Sana"]', '["Bliha","Japra","Dabar","Sana"]', '4', 'Sana. Ostale su kratke kraške ili brdske rječice.', 'The Sana. The others are short karst or hill streams.', 'Wikipedia: Sana (river)', 'https://en.wikipedia.org/wiki/Sana_(river)'),
('sanauna', 'priroda', 'U koju se rijeku kod Novog Grada ulijeva Sana?', 'Which river does the Sana flow into at Novi Grad?', '["Vrbas","Una","Bosna","Neretva"]', '["Vrbas","Una","Bosna","Neretva"]', '2', 'U Unu. Una otiče u Savu, Sava u Dunav, a Dunav u Crno more.', 'The Una. The Una flows into the Sava, the Sava into the Danube and the Danube into the Black Sea.', 'Wikipedia: Sana (river)', 'https://en.wikipedia.org/wiki/Sana_(river)'),
('crnomore', 'priroda', 'U koje more voda Sane stiže preko Une, Save i Dunava?', 'Into which sea does the water of the Sana end up, by way of the Una, Sava and Danube?', '["Jadransko more","Egejsko more","Crno more","Sjeverno more"]', '["Adriatic Sea","Aegean Sea","Black Sea","North Sea"]', '3', 'U Crno more. Sana pripada crnomorskom slivu.', 'Into the Black Sea. The Sana belongs to the Black Sea basin.', 'Wikipedia: Sana (river)', 'https://en.wikipedia.org/wiki/Sana_(river)'),
('izvorsana', 'priroda', 'Kod kojeg mjesta izviru kraški izvori Sane?', 'Near which place do the karst springs of the Sana rise?', '["Ribnik","Jajce","Bihać","Kupres"]', '["Ribnik","Jajce","Bihać","Kupres"]', '1', 'U području Ribnika, u zapadnoj Bosni i Hercegovini.', 'In the Ribnik area, in western Bosnia and Herzegovina.', 'Wikipedia: Sana (river)', 'https://en.wikipedia.org/wiki/Sana_(river)'),
('sanicaus', 'priroda', 'Kod kojeg se sela rječica Sanica ulijeva u Sanu?', 'Near which village does the Sanica join the Sana?', '["Hrustovo","Okreč","Vrhpolje","Lušci Palanka"]', '["Hrustovo","Okreč","Vrhpolje","Lušci Palanka"]', '3', 'Kod Vrhpolja. Sanica je duga oko 22 km.', 'Near Vrhpolje. The Sanica is about 22 km long.', 'Wikipedia: Sanica (river)', 'https://en.wikipedia.org/wiki/Sanica_(river)'),
('najduzarj', 'priroda', 'Koja je od ovih rječica najduža?', 'Which of these small rivers is the longest?', '["Dabar","Kozica","Sanica","Bliha"]', '["Dabar","Kozica","Sanica","Bliha"]', '4', 'Bliha, duga oko 24 km. Sanica ima oko 22 km, Dabar 4,5 km, a Kozica 4 km.', 'The Bliha, about 24 km long. The Sanica is about 22 km, the Dabar 4.5 km and the Kozica 4 km.', 'Wikipedia: Bliha', 'https://en.wikipedia.org/wiki/Bliha'),
('dabarduz', 'priroda', 'Koliko je dugačka rijeka Dabar od izvora do ušća u Sanu?', 'How long is the Dabar river, from its source to the mouth at the Sana?', '["1,5 km","4,5 km","14,5 km","45 km"]', '["1,5 km","4,5 km","14,5 km","45 km"]', '2', 'Samo oko 4,5 km. Izvire iz Dabarske pećine.', 'Only about 4.5 km. It rises from Dabar Cave.', 'Wikipedia: Dabar (river)', 'https://en.wikipedia.org/wiki/Dabar_(river)'),
('dabarime', 'priroda', 'Šta znači ime rijeke Dabar?', 'What does the name of the Dabar river mean?', '["dabar (životinja)","dubina","vidra","brzac"]', '["beaver (the animal)","depth","otter","rapids"]', '1', 'Dabar je životinja (engleski beaver).', 'Dabar means beaver, the animal.', 'Wikipedia: Dabar (river)', 'https://en.wikipedia.org/wiki/Dabar_(river)'),
('blihaizv', 'priroda', 'U kojem selu izvire rijeka Bliha?', 'In which village does the Bliha river rise?', '["Hrustovo","Skucani Vakuf","Donji Lipnik","Podlug"]', '["Hrustovo","Skucani Vakuf","Donji Lipnik","Podlug"]', '3', 'Kod Donjeg Lipnika.', 'Near Donji Lipnik.', 'Wikipedia: Bliha', 'https://en.wikipedia.org/wiki/Bliha'),
('blihavis', 'priroda', 'Koliko je visok vodopad Blihe prema Wikipediji?', 'How high is the Bliha waterfall according to Wikipedia?', '["26 m","56 m","96 m","156 m"]', '["26 m","56 m","96 m","156 m"]', '2', 'Oko 56 m, u jednom padu (neki turistički izvori navode 53 m). Prosječna širina je oko 10 m.', 'About 56 m in a single drop (some tourist sources say 53 m). The average width is about 10 m.', 'Wikipedia: Bliha Falls', 'https://en.wikipedia.org/wiki/Bliha_Falls'),
('blihaskok', 'priroda', 'Kako mještani zovu vodopad Blihe?', 'What do locals call the Bliha waterfall?', '["Blihina suza","Blihin vir","Blihino oko","Blihin skok"]', '["Bliha''s Tear","Bliha''s Whirlpool","Bliha''s Eye","Bliha''s Jump"]', '4', 'Blihin skok (engleski Bliha''s Jump).', 'Blihin skok (Bliha''s Jump).', 'Wikipedia: Bliha Falls', 'https://en.wikipedia.org/wiki/Bliha_Falls'),
('blihakm', 'priroda', 'Koliko je vodopad Blihe udaljen od Sanskog Mosta?', 'How far is the Bliha waterfall from Sanski Most?', '["4 km","14 km","34 km","54 km"]', '["4 km","14 km","34 km","54 km"]', '2', 'Oko 14 km zapadno, kod sela Fajtovci.', 'About 14 km to the west, near the village of Fajtovci.', 'Wikipedia: Bliha Falls', 'https://en.wikipedia.org/wiki/Bliha_Falls'),
('grmec', 'priroda', 'Koja planina zatvara Sanski Most sa zapada?', 'Which mountain closes in Sanski Most from the west?', '["Vlašić","Grmeč","Kozara","Prenj"]', '["Vlašić","Grmeč","Kozara","Prenj"]', '2', 'Grmeč. Na istoku su Mulež i Behremaginica.', 'Grmeč. To the east are Mulež and Behremaginica.', 'Općina Sanski Most: Otkrijte Sanski Most', 'https://sanskimost.gov.ba/otkrijte-sanski-most-biser-krajine-koji-spaja-prirodu-i-tradiciju/'),
('mulez', 'priroda', 'Koje planine su istočno od Sanskog Mosta?', 'Which mountains lie to the east of Sanski Most?', '["Mulež i Behremaginica","Kozara i Prosara","Vlašić i Vranica","Čemernica i Manjača"]', '["Mulež and Behremaginica","Kozara and Prosara","Vlašić and Vranica","Čemernica and Manjača"]', '1', 'Mulež i Behremaginica.', 'Mulež and Behremaginica.', 'Općina Sanski Most: Otkrijte Sanski Most', 'https://sanskimost.gov.ba/otkrijte-sanski-most-biser-krajine-koji-spaja-prirodu-i-tradiciju/'),
('srednjitok', 'priroda', 'U kojem se dijelu toka rijeke Sane nalazi grad?', 'In which part of the Sana''s course does the town lie?', '["U izvorišnom dijelu","U gornjem toku","U srednjem toku","Kod ušća"]', '["At the source","In the upper course","In the middle course","At the mouth"]', '3', 'U srednjem toku.', 'In the middle course.', 'Općina Sanski Most: Historija općine', 'https://sanskimost.gov.ba/historija-opcine-sanski-most/'),
('povgrad', 'priroda', 'Kolika je površina samog gradskog naselja Sanski Most?', 'What is the area of the town of Sanski Most itself?', '["5,9 km²","12,9 km²","29 km²","51 km²"]', '["5,9 km²","12,9 km²","29 km²","51 km²"]', '2', '12,90 km².', '12.90 km².', 'Općina Sanski Most: Otkrijte Sanski Most', 'https://sanskimost.gov.ba/otkrijte-sanski-most-biser-krajine-koji-spaja-prirodu-i-tradiciju/'),
('kanton', 'priroda', 'Kojem kantonu pripada Sanski Most?', 'Which canton does Sanski Most belong to?', '["Unsko-sanski","Zeničko-dobojski","Tuzlanski","Sarajevski"]', '["Unsko-sanski","Zeničko-dobojski","Tuzlanski","Sarajevski"]', '1', 'Unsko-sanskom kantonu Federacije BiH.', 'The Una-Sana Canton of the Federation of Bosnia and Herzegovina.', 'Općina Sanski Most: Otkrijte Sanski Most', 'https://sanskimost.gov.ba/otkrijte-sanski-most-biser-krajine-koji-spaja-prirodu-i-tradiciju/'),
('izmedju', 'priroda', 'Između kojih se gradova nalazi Sanski Most?', 'Between which towns does Sanski Most lie?', '["Banje Luke i Jajca","Bihaća i Cazina","Bosanske Krupe i Bihaća","Prijedora i Ključa"]', '["Banja Luka and Jajce","Bihać and Cazin","Bosanska Krupa and Bihać","Prijedor and Ključ"]', '4', 'Između Prijedora i Ključa, na rijeci Sani.', 'Between Prijedor and Ključ, on the river Sana.', 'Općina Sanski Most: Otkrijte Sanski Most', 'https://sanskimost.gov.ba/otkrijte-sanski-most-biser-krajine-koji-spaja-prirodu-i-tradiciju/'),
('pozivni', 'priroda', 'Koji je telefonski pozivni broj Sanskog Mosta (iza +387)?', 'What is the telephone area code of Sanski Most (after +387)?', '["033","037","038","051"]', '["033","037","038","051"]', '2', '037 (u međunarodnom obliku +387 37).', '037 (+387 37 in international format).', 'Wikipedia: Sanski Most', 'https://en.wikipedia.org/wiki/Sanski_Most'),
('postanski', 'priroda', 'Koji je poštanski broj Sanskog Mosta?', 'What is the postal code of Sanski Most?', '["71000","79260","78000","75000"]', '["71000","79260","78000","75000"]', '2', '79260. Općina se nalazi na adresi Trg ljiljana 1.', '79260. The municipality is at Trg ljiljana 1.', 'Općina Sanski Most: Historija općine', 'https://sanskimost.gov.ba/historija-opcine-sanski-most/'),
('ilidza', 'priroda', 'Po čemu je poznato selo Ilidža podno planine Mulež?', 'What is the village of Ilidža at the foot of Mulež mountain known for?', '["Izvor sumporne vode","Slano jezero","Vrući gejzir","Nalazište nafte"]', '["A sulphur spring","A salt lake","A hot geyser","An oil field"]', '1', 'Po izvoru sumporne vode u podnožju Muleža.', 'For its sulphur spring at the foot of Mulež.', 'Općina Sanski Most: Historija općine', 'https://sanskimost.gov.ba/historija-opcine-sanski-most/'),
('vrelo', 'priroda', 'Koje je od ovih jedno od jakih kraških vrela sanskog područja?', 'Which of these is one of the strong karst springs of the Sanski Most area?', '["Saničko vrelo","Plivsko vrelo","Klokot","Buna"]', '["Sanica spring","Pliva spring","Klokot","Buna"]', '1', 'Saničko vrelo. Uz njega su još Dabarsko vrelo i vrelo Zdene.', 'The Sanica spring. The others are the Dabar spring and the spring of the Zdena.', 'Općina Sanski Most: Historija općine', 'https://sanskimost.gov.ba/historija-opcine-sanski-most/'),
('klima', 'priroda', 'Dolina Sane je otvorena prema ___, pa ovdje vlada srednjoevropska klima. Prema kojoj strani svijeta?', 'The Sana valley is open to the ___, which gives the area a central European climate. To which direction?', '["jugu","zapadu","sjeveru","istoku"]', '["south","west","north","east"]', '3', 'Prema sjeveru.', 'To the north.', 'Općina Sanski Most: Historija općine', 'https://sanskimost.gov.ba/historija-opcine-sanski-most/'),
('pecine2', 'priroda', 'Koje su dvije najveće pećine na području općine?', 'Which two caves are the largest in the municipality?', '["Hrustovačka i Dabarska","Vjetrenica i Hrustovačka","Ledena i Dabarska","Orlovača i Fajtovačka"]', '["Hrustovo and Dabar","Vjetrenica and Hrustovo","Ledena and Dabar","Orlovača and Fajtovci"]', '1', 'Hrustovačka i Dabarska. Spominje se i Fajtovačka pećina.', 'Hrustovo Cave and Dabar Cave. Fajtovci Cave is mentioned too.', 'Općina Sanski Most: Historija općine', 'https://sanskimost.gov.ba/historija-opcine-sanski-most/'),
('dabarpec', 'priroda', 'Iz koje pećine izvire rijeka Dabar?', 'From which cave does the Dabar river rise?', '["Hrustovačke pećine","Dabarske pećine","Fajtovačke pećine","Pećine u Starom Majdanu"]', '["Hrustovo Cave","Dabar Cave","Fajtovci Cave","The caves of Stari Majdan"]', '2', 'Iz Dabarske pećine.', 'From Dabar Cave.', 'Wikipedia: Dabar (river)', 'https://en.wikipedia.org/wiki/Dabar_(river)'),
('septembar', 'priroda', 'Koji je mjesec u Sanskom Mostu najkišovitiji (prosjek 1991 do 2020)?', 'Which month is the wettest in Sanski Most (1991 to 2020 average)?', '["Januar","Juli","April","Septembar"]', '["January","July","April","September"]', '4', 'Septembar, s oko 117,7 mm padavina. Najsuši je august (68,2 mm).', 'September, with about 117.7 mm of rain. The driest is August (68.2 mm).', 'Wikipedia: Sanski Most', 'https://en.wikipedia.org/wiki/Sanski_Most'),
('najsunc', 'priroda', 'U kojem mjesecu u Sanskom Mostu ima najviše sunčanih sati?', 'In which month does Sanski Most get the most hours of sunshine?', '["Maj","Juni","Juli","Septembar"]', '["May","June","July","September"]', '3', 'U julu, oko 291 sat.', 'In July, about 291 hours.', 'Wikipedia: Sanski Most', 'https://en.wikipedia.org/wiki/Sanski_Most'),
('prosjtemp', 'priroda', 'Kolika je prosječna godišnja temperatura u Sanskom Mostu (1991 do 2020)?', 'What is the average annual temperature in Sanski Most (1991 to 2020)?', '["7,2 °C","9,2 °C","11,2 °C","14,2 °C"]', '["7,2 °C","9,2 °C","11,2 °C","14,2 °C"]', '3', 'Oko 11,2 °C.', 'About 11.2 °C.', 'Wikipedia: Sanski Most', 'https://en.wikipedia.org/wiki/Sanski_Most'),
('padavine', 'priroda', 'Koliko padavina u prosjeku godišnje padne u Sanskom Mostu?', 'How much precipitation does Sanski Most get in an average year?', '["562 mm","812 mm","1.062 mm","1.562 mm"]', '["562 mm","812 mm","1.062 mm","1.562 mm"]', '3', 'Oko 1.062 mm.', 'About 1,062 mm.', 'Wikipedia: Sanski Most', 'https://en.wikipedia.org/wiki/Sanski_Most'),
('minus', 'priroda', 'Koliko iznosi rekordno niska temperatura izmjerena u Sanskom Mostu u klimatskom periodu 1991 do 2020?', 'What is the record low temperature measured in Sanski Most in the 1991 to 2020 climate period?', '["−16,4 °C","−26,4 °C","−36,4 °C","−41,0 °C"]', '["−16,4 °C","−26,4 °C","−36,4 °C","−41,0 °C"]', '2', '−26,4 °C.', '−26.4 °C.', 'Wikipedia: Sanski Most', 'https://en.wikipedia.org/wiki/Sanski_Most'),
('visina158', 'priroda', 'Na kojoj nadmorskoj visini leži Sanski Most prema Enciklopediji Jugoslavije iz 1968?', 'At what altitude does Sanski Most lie, according to the 1968 Encyclopaedia of Yugoslavia?', '["58 m","158 m","358 m","558 m"]', '["58 m","158 m","358 m","558 m"]', '2', 'Na 158 m.', 'At 158 m.', 'Općina Sanski Most: Historija općine', 'https://sanskimost.gov.ba/historija-opcine-sanski-most/'),
('ime', 'priroda', 'Šta znači latinska riječ sana, od koje dolazi ime rijeke?', 'What does the Latin word sana, from which the river''s name comes, mean?', '["duboka","zdrava","brza","bistra"]', '["deep","healthy","fast","clear"]', '2', 'Ime dolazi od latinskog sana, „zdrava“, kao u Aqua Sana.', 'The name comes from the Latin sana, “healthy”, as in Aqua Sana.', 'Wikipedia: Sana (river)', 'https://en.wikipedia.org/wiki/Sana_(river)'),
('mazeji', 'historija', 'Koje je ilirsko pleme prema antičkim izvorima živjelo u dolinama Sane i Vrbasa?', 'Which Illyrian tribe, according to ancient sources, lived in the valleys of the Sana and Vrbas?', '["Delmati","Mazeji","Japodi","Breuci"]', '["Delmatae","Maezaei","Iapodes","Breuci"]', '2', 'Mazeji.', 'The Maezaei.', 'Općina Sanski Most: Historija općine', 'https://sanskimost.gov.ba/historija-opcine-sanski-most/'),
('zupe', 'historija', 'Uz sansku, koje su još tri župe prvi put spomenute u povelji Bele IV iz 1244. kao Donji krajevi?', 'Besides the Sana, which three counties are named in Béla IV’s 1244 charter as the Lower Lands?', '["Usorska, soli i zagorska","Dubička, usorska i soli","Dubička, mrenska i vrbaška","Livanjska, glamočka i duvanjska"]', '["Usora, Soli and Zagorje","Dubica, Usora and Soli","Dubica, Mren and Vrbaška","Livno, Glamoč and Duvno"]', '3', 'Dubička, mrenska i vrbaška.', 'Dubica, Mren and Vrbaška.', 'Općina Sanski Most: Historija općine', 'https://sanskimost.gov.ba/historija-opcine-sanski-most/'),
('mihailo', 'historija', 'Kako se zvao sanski župan (knez) spomenut u dokumentu iz 1258?', 'What was the name of the župan (prince) of the Sana mentioned in a document of 1258?', '["Mihailo","Matija Ninoslav","Hrvoje","Stjepan"]', '["Mihailo","Matija Ninoslav","Hrvoje","Stjepan"]', '1', 'Mihailo.', 'Mihailo.', 'Općina Sanski Most: Historija općine', 'https://sanskimost.gov.ba/historija-opcine-sanski-most/'),
('topusko', 'historija', 'Kojoj je opatiji sanski župan 1264. prodao zemlju koja je pripadala kralju?', 'To which abbey did the župan of the Sana sell land in 1264?', '["Čazmi","Topuskom","Lepoglavi","Remetama"]', '["Čazma","Topusko","Lepoglava","Remete"]', '2', 'Opatiji u Topuskom.', 'The abbey at Topusko.', 'Općina Sanski Most: Historija općine', 'https://sanskimost.gov.ba/historija-opcine-sanski-most/'),
('patareni', 'historija', 'Koje su vjeroispovijesti prema dokumentu iz 1304. bili stanovnici Donjih krajeva, što je dovelo do sukoba bana Mladena i Hrvatinića?', 'According to a document of 1304, what was the faith of the inhabitants of the Lower Lands, which led to a conflict between Ban Mladen and the Hrvatinić princes?', '["Patarenske","Pravoslavne","Jevrejske","Katoličke"]', '["Patarene","Orthodox","Jewish","Catholic"]', '1', 'Patarenske. Ban Mladen je bio katolik, a knezovi Hrvatinići patareni.', 'Patarene. Ban Mladen was a Catholic and the Hrvatinić princes were Patarenes.', 'Općina Sanski Most: Historija općine', 'https://sanskimost.gov.ba/historija-opcine-sanski-most/'),
('zagrebb', 'historija', 'Za koju je biskupiju prema dokumentu iz 1334. bio vezan crkveni distrikt Sana?', 'To which diocese was the church district of the Sana tied in a document of 1334?', '["Zagrebačkoj","Đakovačkoj","Splitskoj","Bosanskoj"]', '["Zagreb","Đakovo","Split","Bosnia"]', '1', 'Za zagrebačku biskupiju.', 'To the diocese of Zagreb.', 'Općina Sanski Most: Historija općine', 'https://sanskimost.gov.ba/historija-opcine-sanski-most/'),
